package com.termux.app.workspace;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;
import android.app.Application;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiReplyBudgetTest {
 @Test public void oversizeAnswerReserveShrinksWithoutChangingCurrentRequest()throws Exception{JSONArray h=new JSONArray().put(new JSONObject().put("role","user").put("text","hello"));String original=h.toString();LocalAiReplyBudget.Prepared p=LocalAiReplyBudget.prepare(h,"s",4096,2048,(a,s)->2900,x->{});assertEquals(1132,p.answer);assertEquals(original,p.messages.toString());assertEquals(original,h.toString());}
 @Test public void impossibleCurrentRequestStillFailsRatherThanBeingTruncated()throws Exception{JSONArray h=new JSONArray().put(new JSONObject().put("role","user").put("text","large request"));try{LocalAiReplyBudget.prepare(h,"s",4096,2048,(a,s)->4100,x->{});fail();}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("CONTEXT_TOO_SMALL"));assertEquals("large request",h.getJSONObject(0).getString("text"));}}
 @Test public void fittingReserveIsUnchangedAndMediaCountsUseActualAttachments()throws Exception{JSONArray h=new JSONArray().put(new JSONObject().put("role","user").put("text","x").put("media",new JSONArray().put(new JSONObject().put("path","frame")).put(new JSONObject().put("kind","audio").put("path","sound"))));assertEquals(768,LocalAiReplyBudget.prepare(h,"",4096,768,(a,s)->100,x->{}).answer);assertEquals(1,LocalAiReplyBudget.media(h,"image"));assertEquals(1,LocalAiReplyBudget.media(h,"audio"));}
 @Test public void fieldOrderChangeIsNotReportedAsContextShortening()throws Exception{JSONObject a=new JSONObject().put("role","user").put("text","hello"),b=new JSONObject().put("text","hello").put("role","user");assertTrue(LocalAiContext.same(a,b));java.util.List<String> events=new java.util.ArrayList<>();LocalAiReplyBudget.prepare(new JSONArray().put(a),"",4096,512,LocalAiContext::estimate,events::add);assertTrue(events.isEmpty());}
}
